//! MAC OUI -> vendor lookup.
//!
//! Backed by the full IEEE registry — see `oui_db.rs`, regenerated by
//! `scripts/gen-oui.py`.

use crate::oui_db::OUI_DB;

/// Vendor for a MAC like "d6-0b-ce-71-11-08" or "d6:0b:ce:...", if known.
/// Zero-allocation O(log N) lookup.
pub fn vendor_of(mac: &str) -> Option<&'static str> {
    let mut key = [0u8; 6];
    let mut i = 0;
    for b in mac.bytes() {
        if b.is_ascii_hexdigit() {
            key[i] = b.to_ascii_lowercase();
            i += 1;
            if i == 6 {
                break;
            }
        }
    }
    if i != 6 {
        return None;
    }
    OUI_DB
        .binary_search_by_key(&key, |(prefix, _)| *prefix)
        .ok()
        .map(|idx| OUI_DB[idx].1)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn oui_table_is_sorted_and_unique() {
        for w in OUI_DB.windows(2) {
            assert!(w[0].0 < w[1].0, "OUI table out of order at {:?}", w[0].0);
        }
    }

    #[test]
    fn vendor_lookup() {
        assert_eq!(
            vendor_of("b8-27-eb-00-11-22"),
            Some("Raspberry Pi Foundation")
        );
        assert_eq!(
            vendor_of("B8:27:EB:00:11:22"),
            Some("Raspberry Pi Foundation")
        );
        assert_eq!(vendor_of("ff-ff-ff-00-00-00"), None);
        assert_eq!(vendor_of("garbage"), None);
    }
}
